// holdfast - shared data files: data/lib/*.profile (what a tool needs), data/os/*.profile (what an OS setup is).
// Every data file is a ".profile"; the directory it lives in (profile/, lib/, os/) says what it describes.
//
// Profiles say WHAT they want ([libs] use = python3 git, [profile] os = alpine-dev); these files say WHERE it
// lives. Nothing in a profile is host-specific, so profiles cannot go stale; the one place that can (the
// per-OS lock) is generated by `holdfast libs` and verified by `holdfast libs --check`.
#pragma once
#include <map>
#include <optional>

#include "core/profile.hpp"

namespace hf {

// data/lib/NAME.profile   [lib] description · commands (binaries this lib provides; analysed by `holdfast libs`)
//                           sonames (shared libraries, globs) · paths (data/plugin dirs, globs) · needs (other libs)
struct LibDef {
    std::string name, description;
    Strings commands, sonames, paths, needs;
    fs::path file;
};

enum class OsKind { Host, Bundle };

// data/os/NAME.profile
//   kind = host:   [os] id/version match /etc/os-release; [files.ARCH.LIB] bind = ... (generated by `holdfast libs`)
//   kind = bundle: [os] alpine_version/alpine_mirror/alpine_sha256/packages: one shared Alpine userland
struct OsDef {
    std::string name, description;
    OsKind kind = OsKind::Host;
    fs::path file;
    std::string id, version;
    std::map<std::string, std::map<std::string, Strings>> files;    // arch -> lib -> sandbox paths
    std::string alpine_version, alpine_mirror = "https://dl-cdn.alpinelinux.org/alpine", alpine_sha256;   // version: exact release, required
    Strings packages;
};

struct HostId { std::string id, version; };                         // /etc/os-release ID, VERSION_ID

bool valid_data_name(const std::string& n);                         // becomes a file name: [a-z0-9][a-z0-9._-]{0,63}
// "3.24.3" / "v3.24.3": an exact Alpine release (fetched by name, pinnable). Moving aliases (latest-stable, v3.24, edge) are not.
// *branch receives "v3.24" on success.
bool is_exact_alpine_release(const std::string& v, std::string* branch = nullptr);
// Search order (first match wins): $HOLDFAST_DATA, $HOLDFAST_SHARE/data, ~/.config/holdfast/data, /etc/holdfast/data,
// then the data that ships with holdfast: <dir of the binary>/../data (a checkout or /opt/holdfast) and /opt/holdfast/data.
Strings data_roots(const std::string& home);

LibDef parse_lib(const std::string& text, const std::string& origin, const std::string& name);
OsDef parse_os(const std::string& text, const std::string& origin, const std::string& name);

// data/dep/NAME.profile: one install step for bundle profiles. It runs as an ordinary run of the profile that uses it
// (same userland read-only, same persistent $HOME, same identity, seccomp and terminal filter). Only what it declares differs:
//   [dep]     os (required: must equal the using profile's os) · description · needs (commands that must exist in the userland)
//   [network] mode = none (default) | pasta
//   [install] run = <shell line>, repeatable, executed in order with HOME = the profile's persistent home.
// The recipe is trusted code (like any profile's shell lines): read it before you use it.
DepRecipe parse_dep(const std::string& text, const std::string& origin, const std::string& name);

std::optional<fs::path> find_data(const Strings& roots, const std::string& kind, const std::string& name);   // kind: "lib"|"os"|"dep"|"profile"
LibDef load_lib(const std::string& name, const Strings& roots);
OsDef load_os(const std::string& name, const Strings& roots);
DepRecipe load_dep(const std::string& name, const Strings& roots);
Strings list_data(const Strings& roots, const std::string& kind);   // names, first root wins, sorted

HostId read_host_id(const fs::path& os_release = "/etc/os-release");
std::string suggest_os_name(const HostId& h);                       // "debian-12", "arch"
std::optional<OsDef> match_host_os(const Strings& roots, const HostId& h);   // most specific kind=host definition for h
std::string render_os(const OsDef& o);                               // canonical text of a kind=host file

// Fills what profiles reference by name: bundle profiles get alpine_*/apk_packages/bundle_id from their OS
// file and their data/dep recipes; host profiles with `libs = minimal` get lib_binds from the lib closure of
// [libs] use and the OS file list. [deps] use on a host profile is an error (nothing writable to install into).
// Fails closed: unknown names, uncovered [bin] commands and missing locks are errors that say what to run.
void resolve_profile_data(Profile& p, const Strings& roots);

}  // namespace hf
